/bin/bash -lc "python3 - <<'PY'
import csv, collections, itertools, math
cols=['Bladder','Brain','Cloaca','GallBladder','Gill','Heart','Intestine','Kidney','Limb','Liver','Lung','Pancreas','Prostate','Spleen','Stomach']
sums={'Bladder':701506327,'Brain':1168148790,'Cloaca':484000505,'GallBladder':565994637,'Gill':1094125058,'Heart':868549497,'Intestine':699794434,'Kidney':745602917,'Limb':1147926115,'Liver':398317869,'Lung':877686879,'Pancreas':1398702406,'Prostate':973845979,'Spleen':497829833,'Stomach':455786546}
spots=collections.defaultdict(int); bases=collections.defaultdict(int); spotsA=collections.defaultdict(int); basesA=collections.defaultdict(int)
with open('[REDACTED LOCAL PATH]') as f:
    for r in csv.DictReader(f):
        name=r['SampleName']; p=name.split('_')
        tissue=p[1]
        spots[tissue]+=int(r['spots']); bases[tissue]+=int(r['bases'])
        if len(p)==2 or p[2]=='A':
            spotsA[tissue]+=int(r['spots']); basesA[tissue]+=int(r['bases'])
metrics={'spots_all':spots,'bases_all':bases,'spots_A':spotsA,'bases_A':basesA}
for mname, D in metrics.items():
    vals=[D[c] for c in cols]
    # current pearson/rank
    def pear(a,b):
        ma=sum(a)/len(a); mb=sum(b)/len(b)
        n=sum((x-ma)*(y-mb) for x,y in zip(a,b)); d=math.sqrt(sum((x-ma)**2 for x in a)*sum((y-mb)**2 for y in b)); return n/d
    def rank(arr):
        order=sorted(range(len(arr)), key=lambda i: arr[i]); r=[0]*len(arr); 
        for rankpos,i in enumerate(order): r[i]=rankpos
        return r
    curr_s=[sums[c] for c in cols]
    curr=pear(rank(curr_s),rank(vals))
    best=curr; bestpair=None
    for i,j in itertools.combinations(range(len(cols)),2):
        a=curr_s.copy(); a[i],a[j]=a[j],a[i]
        val=pear(rank(a),rank(vals))
        if val>best: best=val; bestpair=(cols[i],cols[j])
    print(mname,'current rank corr',round(curr,4),'best',round(best,4),'bestpair',bestpair)
    # print top 5 swaps
    arr=[]
    for i,j in itertools.combinations(range(len(cols)),2):
        a=curr_s.copy(); a[i],a[j]=a[j],a[i]
        val=pear(rank(a),rank(vals))
        arr.append((val,(cols[i],cols[j])))
    for val,p in sorted(arr,reverse=True)[:10]: print(' ',round(val,4),p)
PY"

