import csv, collections, statistics
cols=['Bladder','Brain','Cloaca','GallBladder','Gill','Heart','Intestine','Kidney','Limb','Liver','Lung','Pancreas','Prostate','Spleen','Stomach']
sums={'Bladder':701506327,'Brain':1168148790,'Cloaca':484000505,'GallBladder':565994637,'Gill':1094125058,'Heart':868549497,'Intestine':699794434,'Kidney':745602917,'Limb':1147926115,'Liver':398317869,'Lung':877686879,'Pancreas':1398702406,'Prostate':973845979,'Spleen':497829833,'Stomach':455786546}
spots=collections.defaultdict(int); bases=collections.defaultdict(int)
with open('[REDACTED LOCAL PATH]') as f:
    for r in csv.DictReader(f):
